ef\":\"maya/grader-plugins\",\"base_ref\":\"main\",\"base_sha\":\"1a7de90c4b28f6350e9d1c8b7a4f2e6d09c3b5a1\",\"requested_reviewers\":[],\"requested_team_slugs\":[],\"assignees\":[{\"login\":\"maya-ok\",\"avatar_url\":\"\",\"name\":\"Maya Okonkwo\"}],\"reviewed_by_me\":false,\"reactions\":[],\"changed_files\":1,\"commits_count\":1,\"additions\":210,\"deletions\":0,\"comments_count\":0,\"checks_status\":\"pending\",\"mergeable_state\":\"unknown\",\"review_decision\":\"none\"},\"diff\":\"diff --git a/evalkit/plugins.py b/evalkit/plugins.py\\nnew file mode 100644\\nindex 0000000..c93b7e1\\n--- /dev/null\\n+++ b/evalkit/plugins.py\\n@@ -0,0 +1,24 @@\\n+\\\"\\\"\\\"Load path for custom graders.\\n+\\n+Sandboxing is deliberately NOT part of this draft: an in-process\\n+plugin that can `import os` is a judgment we keep getting wrong\\n+automatically, so it needs its own review pass.\\\"\\\"\\\"\\n+\\n+class GraderPlugin:\\n+    def __init__(self, name, path):\\n+        self.name = name\\n+        self.path = path\\n\",\"files\":[{\"filename\":\"evalkit/plugins.py\",\"status\":\"added\",\"additions\":210,\"deletions\":0,\"patch\":\"@@ -0,0 +1,24 @@\\n+class GraderPlugin:\\n+    def __init__(self, name, path):\\n+        self.name = name\\n+        self.path = path\",\"viewed_state\":\"unviewed\"}],\"commits\":[{\"sha\":\"c93b7e1a5d284f60b7e2c9a1d5f38b04e7c2a916\",\"message\":\"Grader plugin protocol + load path\",\"author\":{\"login\":\"maya-ok\",\"avatar_url\":\"\",\"name\":\"Maya Okonkwo\"},\"date\":\"@-9h\"}],\"reviews\":[],\"review_comments\":[],\"issue_comments\":[],\"timeline\":[],\"check_runs\":[{\"name\":\"analyze\",\"status\":\"inProgress\",\"html_url\":\"\",\"started_at\":\"@-9h\",\"output\":\"\",\"workflow_name\":\"ci\"},{\"name\":\"test\",\"status\":\"queued\",\"html_url\":\"\",\"output\":\"\",\"workflow_name\":\"ci\"}],\"commit_statuses\":[{\"context\":\"ci/build\",\"state\":\"pending\",\"description\":\"Build running\",\"target_url\":\"\",\"created_at\":\"@-9h\"}],\"reviewers\":[]},{\"detail\":{\"id\":880001,\"number\":88,\"title\":\"Add hybrid BM25 + embedding retrieval\",\"body\":\"Dense retrieval alone misses exact identifiers (dataset ids, citation keys). This unions BM25 over the chunk index with the existing embedding search and Reciprocal Rank Fusion, so a query that names a paper id still ranks that chunk first.\\n\\nFixes HX-118's cousin on the retrieval side — long traces were timing out in the dense-only path.\",\"state\":\"open\",\"is_draft\":false,\"author\":{\"login\":\"priya-r\",\"avatar_url\":\"\",\"name\":\"Priya Raman\"},\"created_at\":\"@-5d\",\"updated_at\":\"@-8h\",\"repo_full_name\":\"helix/retriever\",\"html_url\":\"https://example.invalid/helix/retriever/pull/88\",\"external_id\":\"PR_88\",\"head_sha\":\"b71e4c9d3a25f80c6e1b7d94a3f28c05e6d1b7a4\",\"head_ref\":\"priya/hybrid-retrieval\",\"base_ref\":\"main\",\"base_sha\":\"2c8de91d5b39f7461f0e2d9c8b5f3e7e10d4c6b2\",\"requested_reviewers\":[],\"requested_team_slugs\":[\"ml-eng\"],\"assignees\":[],\"labels\":[{\"name\":\"enhancement\",\"color\":\"a2eeef\",\"description\":\"New feature or request\"}],\"reviewed_by_me\":false,\"reactions\":[],\"changed_files\":2,\"commits_count\":3,\"additions\":94,\"deletions\":12,\"comments_count\":3,\"checks_status\":\"passing\",\"mergeable_state\":\"clean\",\"review_decision\":\"reviewRequired\"},\"diff\":\"diff --git a/retriever/hybrid.py b/retriever/hybrid.py\\nindex 22c9f1e..b71e4c9 100644\\n--- a/retriever/hybrid.py\\n+++ b/retriever/hybrid.py\\n@@ -18,8 +18,16 @@ class Retriever:\\n     def search(self, query, k=8):\\n-        return self._dense.search(query, k)\\n+        dense = self._dense.search(query, k * 2)\\n+        sparse = self._bm25.search(query, k * 2)\\n+        return rrf(dense, sparse)[:k]\\n\",\"files\":[{\"filename\":\"retriever/hybrid.py\",\"status\":\"modified\",\"additions\":62,\"deletions\":8,\"patch\":\"@@ -18,8 +18,16 @@ class Retriever:\\n+        dense = self._dense.search(query, k * 2)\\n+        sparse = self._bm25.search(query, k * 2)\\n+        return rrf(dense, sparse)[:k]\",\"viewed_state\":\"unviewed\"},{\"filename\":\"retriever/rrf.py\",\"status\":\"added\",\"additions\":32,\"deletions\":0,\"patch\":\"@@ -0,0 +1,16 @@\\n+def rrf(*rankings, k=60):\\n+    scores = {}\\n+    for ranking in rankings:\\n+        for i, doc in enumerate(ranking):\\n+            scores[doc.id] = scores.get(doc.id, 0) + 1 / (k + i + 1)\\n+    return sorted(scores, key=scores.get, reverse=True)\",\"viewed_state\":\"unviewed\"}],\"commits\":[{\"sha\":\"e5c1a7b93d604f28a1c7e9b5d0f3a682c4b91d7e\",\"message\":\"Add BM25 over the chunk index\",\"author\":{\"login\":\"priya-r\",\"avatar_url\":\"\",\"name\":\"Priya Raman\"},\"date\":\"@-5d\"},{\"sha\":\"a4d2c8e17b503f19c0d6e8a4f1e27b94d5c0a8f3\",\"message\":\"Fuse with reciprocal rank fusion\",\"author\":{\"login\":\"priya-r\",\"avatar_url\":\"\",\"name\":\"Priya Raman\"},\"date\":\"@-2d\"},{\"sha\":\"b71e4c9d3a25f80c6e1b7d94a3f28c05e6d1b7a4\",\"message\":\"Pin identifier queries in the retrieval suite\",\"author\":{\"login\":\"priya-r\",\"avatar_url\":\"\",\"name\":\"Priya Raman\"},\"date\":\"@-8h\"}],\"reviews\":[],\"review_comments\":[],\"issue_comments\":[{\"id\":7801,\"body\":\"Taking the ml-eng request. Identifier queries (dataset ids, citation keys) have to rank the named chunk first — I'll check that against the retrieval suite before approving.\",\"user\":{\"login\":\"maya-ok\",\"avatar_url\":\"\",\"name\":\"Maya Okonkwo\"},\"created_at\":\"@-10h\",\"reactions\":[]},{\"id\":7802,\"body\":\"The suite now pins `ds_7f3a` and `cite:kr2023`. Ready when you are.\",\"user\":{\"login\":\"priya-r\",\"avatar_url\":\"\",\"name\":\"Priya Raman\"},\"created_at\":\"@-8h\",\"reactions\":[]}],\"timeline\":[{\"kind\":\"labeled\",\"actor\":{\"login\":\"priya-r\",\"avatar_url\":\"\",\"name\":\"Priya Raman\"},\"label\":{\"name\":\"enhancement\",\"color\":\"a2eeef\",\"description\":\"New feature or request\"},\"created_at\":\"@-5d\"},{\"kind\":\"reviewRequested\",\"actor\":{\"login\":\"priya-r\",\"avatar_url\":\"\",\"name\":\"Priya Raman\"},\"reviewer_name\":\"ml-eng\",\"reviewer_is_team\":true,\"reviewer_avatar_url\":\"\",\"created_at\":\"@-5d\"}],\"check_runs\":[{\"name\":\"test\",\"status\":\"completed\",\"conclusion\":\"success\",\"html_url\":\"\",\"started_at\":\"@-8h\",\"completed_at\":\"@-8h\",\"output\":\"96 passed\",\"workflow_name\":\"ci\"}],\"commit_statuses\":[],\"reviewers\":[{\"kind\":\"team\",\"name\":\"ML eng\",\"slug\":\"ml-eng\",\"avatar_url\":\"\",\"is_code_owner\":true,\"state\":\"pending\"}]},{\"detail\":{\"id\":810001,\"number\":81,\"title\":\"Reranker timeout is silently swallowed\",\"body\":\"When the cross-encoder times out we currently return the unre-ranked dense hits and log a warning. Callers treat that as a successful hybrid search, so a 504 looks like \\\"the corpus has no good matches\\\".\\n\\nThis fails the request instead, with a distinct `RerankTimeout` the run card can show.\\n\\nFixes HX-124.\",\"state\":\"open\",\"is_draft\":false,\"author\":{\"login\":\"maya-ok\",\"avatar_url\":\"\",\"name\":\"Maya Okonkwo\"},\"created_at\":\"@-4d\",\"updated_at\":\"@-6h\",\"repo_full_name\":\"helix/retriever\",\"html_url\":\"https://example.invalid/helix/retriever/pull/81\",\"external_id\":\"PR_81\",\"head_sha\":\"d40a6c2b81e795f3c0a6b8d2e4f17c93b5a0e6d8\",\"head_ref\":\"maya/rerank-timeout\",\"base_ref\":\"main\",\"base_sha\":\"2c8de91d5b39f7461f0e2d9c8b5f3e7e10d4c6b2\",\"requested_reviewers\":[{\"login\":\"dferrer\",\"avatar_url\":\"\",\"name\":\"Diego Ferrer\"}],\"requested_team_slugs\":[],\"assignees\":[{\"login\":\"maya-ok\",\"avatar_url\":\"\",\"name\":\"Maya Okonkwo\"}],\"labels\":[{\"name\":\"bug\",\"color\":\"d73a4a\",\"description\":\"Something isn't working\"}],\"reviewed_by_me\":false,\"reactions\":[],\"changed_files\":2,\"commits_count\":2,\"additions\":48,\"deletions\":11,\"comments_count\":2,\"checks_status\":\"failing\",\"mergeable_state\":\"blocked\",\"review_decision\":\"changesRequested\"},\"diff\":\"diff --git a/retriever/rerank.py b/retriever/rerank.py\\nindex 5a0e6d8..d40a6c2 100644\\n--- a/retriever/rerank.py\\n+++ b/retriever/rerank.py\\n@@ -22,9 +22,8 @@ class Reranker:\\n         try:\\n             return self._model.predict(pairs, timeout=self._timeout)\\n         except TimeoutError:\\n-            log.warning(\\\"rerank timed out; returning unre-ranked hits\\\")\\n-            return hits\\n+            raise RerankTimeout(self._timeout) from None\\n\",\"files\":[{\"filename\":\"retriever/rerank.py\",\"status\":\"modified\",\"additions\":28,\"deletions\":7,\"patch\":\"@@ -22,9 +22,8 @@ class Reranker:\\n-            log.warning(\\\"rerank timed out; returning unre-ranked hits\\\")\\n-            return hits\\n+            raise RerankTimeout(self._timeout) from None\",\"viewed_state\":\"unviewed\"},{\"filename\":\"tests/retriever/test_rerank.py\",\"status\":\"modified\",\"additions\":20,\"deletions\":4,\"patch\":\"@@ -40,6 +40,14 @@\\n+def test_timeout_is_a_hard_failure():\\n+    with pytest.raises(RerankTimeout):\\n+        reranker.rerank(hits, query=\\\"q\\\")\",\"viewed_state\":\"unviewed\"}],\"commits\":[{\"sha\":\"c1b8d4e92a715f30b2d7c9e5f0a38c04d6b1e8a7\",\"message\":\"Fail the request when the reranker times out\",\"author\":{\"login\":\"maya-ok\",\"avatar_url\":\"\",\"name\":\"Maya Okonkwo\"},\"date\":\"@-4d\"},{\"sha\":\"d40a6c2b81e795f3c0a6b8d2e4f17c93b5a0e6d8\",\"message\":\"Pin the timeout as a hard failure\",\"author\":{\"login\":\"maya-ok\",\"avatar_url\":\"\",\"name\":\"Maya Okonkwo\"},\"date\":\"@-6h\"}],\"reviews\":[{\"id\":9101,\"state\":\"changesRequested\",\"author\":{\"login\":\"dferrer\",\"avatar_url\":\"\",\"name\":\"Diego Ferrer\"},\"body\":\"The fail-closed call is right, but the new test never injects a clock — it sleeps the real timeout, so CI flakes when the runner is busy. Pass a `timeout=0` reranker in the test, or this stays red.\",\"submitted_at\":\"@-6h\",\"reactions\":[]}],\"review_comments\":[],\"issue_comments\":[{\"id\":7901,\"body\":\"The fail-closed call is the right shape. I'll hold merge until the test injects `timeout=0` — sleeping the real timeout is what made CI red.\",\"user\":{\"login\":\"maya-ok\",\"avatar_url\":\"\",\"name\":\"Maya Okonkwo\"},\"created_at\":\"@-5h\",\"reactions\":[]}],\"timeline\":[{\"kind\":\"labeled\",\"actor\":{\"login\":\"maya-ok\",\"avatar_url\":\"\",\"name\":\"Maya Okonkwo\"},\"label\":{\"name\":\"bug\",\"color\":\"d73a4a\",\"description\":\"Something isn't working\"},\"created_at\":\"@-4d\"}],\"check_runs\":[{\"name\":\"analyze\",\"status\":\"completed\",\"conclusion\":\"success\",\"html_url\":\"\",\"started_at\":\"@-6h\",\"completed_at\":\"@-6h\",\"output\":\"No issues found\",\"workflow_name\":\"ci\"},{\"name\":\"test\",\"status\":\"completed\",\"conclusion\":\"failure\",\"html_url\":\"\",\"started_at\":\"@-6h\",\"completed_at\":\"@-6h\",\"output\":\"1 failing: test_rerank.py — reranker slept the real timeout\",\"workflow_name\":\"ci\"}],\"commit_statuses\":[{\"context\":\"ci/build\",\"state\":\"failure\",\"description\":\"1 test failed\",\"target_url\":\"\",\"created_at\":\"@-6h\"}],\"reviewers\":[{\"kind\":\"user\",\"user\":{\"login\":\"dferrer\",\"avatar_url\":\"\",\"name\":\"Diego Ferrer\"},\"is_code_owner\":false,\"state\":\"changesRequested\"}]},{\"detail\":{\"id\":540001,\"number\":54,\"title\":\"Materialize late-arriving features on read\",\"body\":\"Online features that land after the training window currently 404 the serving path. This backfills on read from the offline store (capped at 50ms) so a feature that arrived 2s late still serves rather than dropping the example.\\n\\nWaiting on a first pass from Diego.\",\"state\":\"open\",\"is_draft\":false,\"author\":{\"login\":\"maya-ok\",\"avatar_url\":\"\",\"name\":\"Maya Okonkwo\"},\"created_at\":\"@-3d\",\"updated_at\":\"@-14h\",\"repo_full_name\":\"helix/features\",\"html_url\":\"https://example.invalid/helix/features/pull/54\",\"external_id\":\"PR_54\",\"head_sha\":\"a91c4e8b72d604f19b3e7a5c0d28f16e4b9c0d7a\",\"head_ref\":\"maya/late-features\",\"base_ref\":\"main\",\"base_sha\":\"3d9ef02e6c40a8572a1f3e0d9c6a4f8f21e5d7c3\",\"requested_reviewers\":[{\"login\":\"dferrer\",\"avatar_url\":\"\",\"name\":\"Diego Ferrer\"}],\"requested_team_slugs\":[],\"assignees\":[{\"login\":\"maya-ok\",\"avatar_url\":\"\",\"name\":\"Maya Okonkwo\"}],\"labels\":[{\"name\":\"enhancement\",\"color\":\"a2eeef\",\"description\":\"New feature or request\"}],\"reviewed_by_me\":false,\"reactions\":[],\"changed_files\":2,\"commits_count\":2,\"additions\":76,\"deletions\":9,\"comments_count\":0,\"checks_status\":\"passing\",\"mergeable_state\":\"clean\",\"review_decision\":\"none\"},\"diff\":\"diff --git a/features/serve.py b/features/serve.py\\nindex 11aa22b..a91c4e8 100644\\n--- a/features/serve.py\\n+++ b/features/serve.py\\n@@ -30,7 +30,12 @@ class FeatureStore:\\n     def get(self, entity_id, name):\\n         row = self._online.get(entity_id, name)\\n-        if row is None:\\n-            raise FeatureMissing(name)\\n+        if row is None:\\n+            row = self._offline.get(entity_id, name, timeout_ms=50)\\n+            if row is None:\\n+                raise FeatureMissing(name)\\n         return row\\n\",\"files\":[{\"filename\":\"features/serve.py\",\"status\":\"modified\",\"additions\":48,\"deletions\":6,\"patch\":\"@@ -30,7 +30,12 @@ class FeatureStore:\\n+            row = self._offline.get(entity_id, name, timeout_ms=50)\",\"viewed_state\":\"unviewed\"},{\"filename\":\"tests/features/test_serve.py\",\"status\":\"modified\",\"additions\":28,\"deletions\":3,\"patch\":\"@@ -22,6 +22,14 @@\\n+def test_late_feature_materializes_from_offline():\\n+    assert store.get(\\\"e1\\\", \\\"clicks_1h\\\") == 4\",\"viewed_state\":\"unviewed\"}],\"commits\":[{\"sha\":\"8e2f1c4a93b705d20c4d8f6b1e39a05c7d2b9e18\",\"message\":\"Backfill late features from the offline store\",\"author\":{\"login\":\"maya-ok\",\"avatar_url\":\"\",\"name\":\"Maya Okonkwo\"},\"date\":\"@-3d\"},{\"sha\":\"a91c4e8b72d604f19b3e7a5c0d28f16e4b9c0d7a\",\"message\":\"Cap the offline read at 50ms\",\"author\":{\"login\":\"maya-ok\",\"avatar_url\":\"\",\"name\":\"Maya Okonkwo\"},\"date\":\"@-14h\"}],\"reviews\":[],\"review_comments\":[],\"issue_comments\":[],\"timeline\":[{\"kind\":\"reviewRequested\",\"actor\":{\"login\":\"maya-ok\",\"avatar_url\":\"\",\"name\":\"Maya Okonkwo\"},\"reviewer_name\":\"dferrer\",\"reviewer_is_team\":false,\"reviewer_avatar_url\":\"\",\"created_at\":\"@-3d\"}],\"check_runs\":[{\"name\":\"test\",\"status\":\"completed\",\"conclusion\":\"success\",\"html_url\":\"\",\"started_at\":\"@-14h\",\"completed_at\":\"@-14h\",\"output\":\"41 passed\",\"workflow_name\":\"ci\"}],\"commit_statuses\":[],\"reviewers\":[{\"kind\":\"user\",\"user\":{\"login\":\"dferrer\",\"avatar_url\":\"\",\"name\":\"Diego Ferrer\"},\"is_code_owner\":true,\"state\":\"pending\"}]},{\"detail\":{\"id\":490001,\"number\":49,\"title\":\"Feature lineage graph\",\"body\":\"Walks producers → consumers so a broken transform names every serving path it hits. Maya already reviewed; I am folding her nits.\",\"state\":\"open\",\"is_draft\":false,\"author\":{\"login\":\"dferrer\",\"avatar_url\":\"\",\"name\":\"Diego Ferrer\"},\"created_at\":\"@-6d\",\"updated_at\":\"@-1d\",\"repo_full_name\":\"helix/features\",\"html_url\":\"https://example.invalid/helix/features/pull/49\",\"external_id\":\"PR_49\",\"head_sha\":\"f12a7d3c90e816b4d1c8f9a6e5b30d27c8a4f1e9\",\"head_ref\":\"diego/lineage-graph\",\"base_ref\":\"main\",\"base_sha\":\"3d9ef02e6c40a8572a1f3e0d9c6a4f8f21e5d7c3\",\"requested_reviewers\":[],\"requested_team_slugs\":[],\"assignees\":[{\"login\":\"dferrer\",\"avatar_url\":\"\",\"name\":\"Diego Ferrer\"}],\"labels\":[{\"name\":\"enhancement\",\"color\":\"a2eeef\",\"description\":\"New feature or request\"}],\"reviewed_by_me\":true,\"reactions\":[{\"content\":\"THUMBS_UP\",\"emoji\":\"👍\",\"count\":1,\"user_reacted\":true,\"usernames\":[\"maya-ok\"]}],\"changed_files\":2,\"commits_count\":3,\"additions\":132,\"deletions\":4,\"comments_count\":2,\"checks_status\":\"passing\",\"mergeable_state\":\"clean\",\"review_decision\":\"approved\"},\"diff\":\"diff --git a/features/lineage.py b/features/lineage.py\\nnew file mode 100644\\nindex 0000000..f12a7d3\\n--- /dev/null\\n+++ b/features/lineage.py\\n@@ -0,0 +1,28 @@\\n+class LineageGraph:\\n+    def consumers(self, feature):\\n+        return list(self._edges.get(feature, ()))\\n\",\"files\":[{\"filename\":\"features/lineage.py\",\"status\":\"added\",\"additions\":110,\"deletions\":0,\"patch\":\"@@ -0,0 +1,28 @@\\n+class LineageGraph:\\n+    def consumers(self, feature):\\n+        return list(self._edges.get(feature, ()))\",\"viewed_state\":\"viewed\"},{\"filename\":\"tests/features/test_lineage.py\",\"status\":\"added\",\"additions\":22,\"deletions\":0,\"patch\":\"@@ -0,0 +1,10 @@\\n+def test_a_broken_transform_names_its_serving_paths():\\n+    assert graph.consumers(\\\"clicks_1h\\\") == [\\\"ranker\\\", \\\"eval\\\"]\",\"viewed_state\":\"viewed\"}],\"commits\":[{\"sha\":\"b3c9e1f84a726d31e5f8a0c2d47b16d9e3c5a082\",\"message\":\"Lineage graph over feature producers\",\"author\":{\"login\":\"dferrer\",\"avatar_url\":\"\",\"name\":\"Diego Ferrer\"},\"date\":\"@-6d\"},{\"sha\":\"c4d0f2a95b837e42f6a9b1d3e58c27e0f4d6b193\",\"message\":\"Name every serving path a transform hits\",\"author\":{\"login\":\"dferrer\",\"avatar_url\":\"\",\"name\":\"Diego Ferrer\"},\"date\":\"@-3d\"},{\"sha\":\"f12a7d3c90e816b4d1c8f9a6e5b30d27c8a4f1e9\",\"message\":\"Fold Maya's nits on the walk order\",\"author\":{\"login\":\"dferrer\",\"avatar_url\":\"\",\"name\":\"Diego Ferrer\"},\"date\":\"@-1d\"}],\"reviews\":[{\"id\":9201,\"state\":\"approved\",\"author\":{\"login\":\"maya-ok\",\"avatar_url\":\"\",\"name\":\"Maya Okonkwo\"},\"body\":\"Approved — walk order is topological now, so a cycle fails closed instead of looping. The serving-path names match what evalkit already logs.\",\"submitted_at\":\"@-1d\",\"reactions\":[]}],\"review_comments\":[],\"issue_comments\":[],\"timeline\":[],\"check_runs\":[{\"name\":\"test\",\"status\":\"completed\",\"conclusion\":\"success\",\"html_url\":\"\",\"started_at\":\"@-1d\",\"completed_at\":\"@-1d\",\"output\":\"41 passed\",\"workflow_name\":\"ci\"}],\"commit_statuses\":[],\"reviewers\":[{\"kind\":\"user\",\"user\":{\"login\":\"maya-ok\",\"avatar_url\":\"\",\"name\":\"Maya Okonkwo\"},\"is_code_owner\":true,\"state\":\"approved\"}]},{\"detail\":{\"id\":230001,\"number\":23,\"title\":\"LoRA adapter merge is not deterministic\",\"body\":\"Merging the same adapter twice produced different weights because `torch.add` ran without a pinned generator. This seeds the merge from the adapter hash so two merges of the same artifact byte-compare.\\n\\nDiego approved; landing once CI is green.\",\"state\":\"open\",\"is_draft\":false,\"author\":{\"login\":\"maya-ok\",\"avatar_url\":\"\",\"name\":\"Maya Okonkwo\"},\"created_at\":\"@-2d\",\"updated_at\":\"@-3h\",\"repo_full_name\":\"helix/finetune\",\"html_url\":\"https://example.invalid/helix/finetune/pull/23\",\"external_id\":\"PR_23\",\"head_sha\":\"e81b5d4a03c927e6f2b9c1d8a7e40f38d6c2b5a1\",\"head_ref\":\"maya/lora-merge-seed\",\"base_ref\":\"main\",\"base_sha\":\"4e0fa13f7d51b9683a2a4f1e0d7a5a9a32f6e8d4\",\"requested_reviewers\":[],\"requested_team_slugs\":[],\"assignees\":[{\"login\":\"maya-ok\",\"avatar_url\":\"\",\"name\":\"Maya Okonkwo\"}],\"labels\":[{\"name\":\"bug\",\"color\":\"d73a4a\",\"description\":\"Something isn't working\"}],\"reviewed_by_me\":false,\"reactions\":[{\"content\":\"ROCKET\",\"emoji\":\"🚀\",\"count\":1,\"user_reacted\":false,\"usernames\":[\"dferrer\"]}],\"changed_files\":2,\"commits_count\":2,\"additions\":36,\"deletions\":8,\"comments_count\":1,\"checks_status\":\"passing\",\"mergeable_state\":\"clean\",\"review_decision\":\"approved\"},\"diff\":\"diff --git a/finetune/merge.py b/finetune/merge.py\\nindex 88bb99c..e81b5d4 100644\\n--- a/finetune/merge.py\\n+++ b/finetune/merge.py\\n@@ -14,7 +14,9 @@ def merge(base, adapter):\\n-    torch.manual_seed(0)\\n+    torch.manual_seed(_seed_from(adapter.hash))\\n     return base + adapter.delta\\n\",\"files\":[{\"filename\":\"finetune/merge.py\",\"status\":\"modified\",\"additions\":22,\"deletions\":6,\"patch\":\"@@ -14,7 +14,9 @@ def merge(base, adapter):\\n-    torch.manual_seed(0)\\n+    torch.manual_seed(_seed_from(adapter.hash))\",\"viewed_state\":\"viewed\"},{\"filename\":\"tests/finetune/test_merge.py\",\"status\":\"modified\",\"additions\":14,\"deletions\":2,\"patch\":\"@@ -8,6 +8,12 @@\\n+def test_two_merges_of_the_same_adapter_byte_compare():\\n+    assert merge(base, adapter) == merge(base, adapter)\",\"viewed_state\":\"viewed\"}],\"commits\":[{\"sha\":\"c9d4e2b81a637f50d3e8b1c6f29a14e8c5b3d092\",\"message\":\"Seed LoRA merge from the adapter hash\",\"author\":{\"login\":\"maya-ok\",\"avatar_url\":\"\",\"name\":\"Maya Okonkwo\"},\"date\":\"@-2d\"},{\"sha\":\"e81b5d4a03c927e6f2b9c1d8a7e40f38d6c2b5a1\",\"message\":\"Pin two merges of the same adapter\",\"author\":{\"login\":\"maya-ok\",\"avatar_url\":\"\",\"name\":\"Maya Okonkwo\"},\"date\":\"@-3h\"}],\"reviews\":[{\"id\":9301,\"state\":\"approved\",\"author\":{\"login\":\"dferrer\",\"avatar_url\":\"\",\"name\":\"Diego Ferrer\"},\"body\":\"Approved — I reran the merge twice locally and the tensors byte-compare. Nice.\",\"submitted_at\":\"@-3h\",\"reactions\":[]}],\"review_comments\":[],\"issue_comments\":[],\"timeline\":[{\"kind\":\"labeled\",\"actor\":{\"login\":\"maya-ok\",\"avatar_url\":\"\",\"name\":\"Maya Okonkwo\"},\"label\":{\"name\":\"bug\",\"color\":\"d73a4a\",\"description\":\"Something isn't working\"},\"created_at\":\"@-2d\"}],\"check_runs\":[{\"name\":\"test\",\"status\":\"completed\",\"conclusion\":\"success\",\"html_url\":\"\",\"started_at\":\"@-3h\",\"completed_at\":\"@-3h\",\"output\":\"28 passed\",\"workflow_name\":\"ci\"}],\"commit_statuses\":[],\"reviewers\":[